intro:
Outputs a textual representation of mdl into os, as if by

os << std::format(os.getloc(), STATICALLY_WIDEN<CharT>("{:L}/last"), mdl.month());

where STATICALLY_WIDEN<CharT>("{:L}/last") is "{:L}/last" if CharT is char, and L"{:L}/last" if CharT is wchar_t.

examples.code:
#include <chrono>
#include <format>
#include <sstream>
#include <string>
#include <cassert>
#include <iostream>

int main() {
    using namespace std::chrono;
    month_day_last date{March / last};
    assert(date.ok());
    std::ostringstream text;
    text << date;
    assert(!text.str().empty());
    auto formatted = std::format("{}", date);
    assert(!formatted.empty());
    std::cout << "Checks passed\n";
}
